        return r

    w = i(observation.get("grid_width", observation.get("width", 0)))
    h = i(observation.get("grid_height", observation.get("height", 0)))
    sx, sy = p(observation.get("self_position", observation.get("position", (0, 0))))
    ox, oy = p(observation.get("opponent_position", observation.get("enemy_position", (10**9, 10**9))))
    resources = pts(observation.get("resources", []))
    obstacles = set(pts(observation.get("obstacles", [])))
    obstacles |= set(pts(observation.get("walls", [])))
    obstacles |= set(pts(observation.get("self_path", [])))
    obstacles |= set(pts(observation.get("opponent_path", [])))
    owned = set(pts(observation.get("owned", observation.get("territory", []))))
    trail = set(pts(observation.get("trail", [])))

    dirs = [(0, 0), (0, -1), (1, 0), (0, 1), (-1, 0)]

